using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ChangeDiceActionForOneTurnAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/ChangeDiceActionForOneTurn Action")]
public class ChangeDiceActionForOneTurnAction : ChooseDiceAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private BattleAction actionToChange;

	[SerializeField]
	private bool notAffectedByDoom;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private bool enableExtraBattleAction;

	[SerializeField]
	[ShowIf("enableExtraBattleAction")]
	private BattleAction extraBattleAction;

	[SerializeField]
	[ShowIf("enableExtraBattleAction")]
	private int extraActionValue;

	[SerializeField]
	[ShowIf("enableExtraBattleAction")]
	private OmenLogic extraBattleActionOmenLogic;

	[SerializeField]
	private bool selenicDomination;

	public BattleAction ActionToChange => actionToChange;

	public bool NotAffectedByDoom => notAffectedByDoom;

	public bool EnableExtraBattleAction => enableExtraBattleAction;

	public BattleAction ExtraBattleAction => extraBattleAction;

	public int ExtraActionValue => extraActionValue;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		int num = 0;
		for (int i = 0; i < currentCorruptedAnimals.activeCorruptedAnimals.Count; i++)
		{
			num += currentCorruptedAnimals.activeCorruptedAnimals[i].GetComponent<UnitsDiceActivation>().GetDiceInstancesToRoll(ignoreDisabledActions: true).Count;
		}
		if (num == 0)
		{
			return false;
		}
		return true;
	}

	public override void CastAmount(int amount, GameObject source)
	{
		if (enableExtraBattleAction)
		{
			if (selenicDomination)
			{
				if (extraBattleAction.CheckConditionToBeCasted(playerHand: false, DiceOwnerEnum.PLAYER))
				{
					extraBattleActionOmenLogic.ActivateOmen(extraBattleAction, extraActionValue, null, source);
				}
				else
				{
					ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
				}
			}
			else
			{
				extraBattleActionOmenLogic.ActivateOmen(extraBattleAction, extraActionValue, null, source);
			}
		}
		bool flag = IsVFXEnabled();
		for (int i = 0; i < diceList.Count; i++)
		{
			DiceInstance diceInstance = diceList[i];
			diceInstance.ActionFace.BattleAction = actionToChange;
			diceInstance.ActionFace.NewBattleAction = actionToChange;
			diceInstance.ActionFace.ActionValue = amount;
			diceInstance.ActionFace.NewActionValue = amount;
			diceInstance.ActionFace.EnableSecondAction = false;
			diceInstance.ActionFace.SecondBattleAction = null;
			diceInstance.ActionFace.SecondActionValue = 0;
			if (notAffectedByDoom)
			{
				diceInstance.ActionFace.RemoveActionValueModifier(BattleActionInteractionEnum.CORRUPT);
				diceInstance.ActionFace.SetActionModifierLock(isLocked: true);
			}
			else
			{
				diceInstance.ActionOwner.GetComponent<UnitEffects>().UpdateActionValueModifier();
			}
			diceInstance.UpdateDiceFace();
			if (i == diceList.Count - 1)
			{
				if (!enableExtraBattleAction)
				{
					ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
				}
				diceInstance.GoBackToOriginalPositionAnimation(returningToHandAfterDrag: false, delegate
				{
					ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState(WaitForFramesType.NoFrame);
				});
			}
			else
			{
				diceInstance.GoBackToOriginalPositionAnimation();
			}
			if (flag)
			{
				GetVFX(4f).GetComponent<ParticleFollower>().Initialize(diceInstance);
			}
		}
		if (flag)
		{
			PlaySFX();
		}
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
	}
}
